using DriveOS.Modules.CurriculumPedagogy.Domain.Readiness.Events;using DriveOS.SharedKernel.Auditing;using DriveOS.SharedKernel.Domain;using DriveOS.SharedKernel.Identifiers;using DriveOS.SharedKernel.Results;
namespace DriveOS.Modules.CurriculumPedagogy.Domain.Readiness;
public sealed class PedagogicalReadinessDecision:AggregateRoot<PedagogicalReadinessDecisionId>,IAuditableEntity{private PedagogicalReadinessDecision(){}private PedagogicalReadinessDecision(PedagogicalReadinessDecisionId id,OrganizationId org,PersonId student,TrainingPathId path,PedagogicalReadinessDecisionStatus decision,string rationale,string? conditions,UserId reviewer,DateTimeOffset decidedAt):base(id){OrganizationId=org;StudentId=student;TrainingPathId=path;Decision=decision;Rationale=rationale;Conditions=conditions;ReviewerId=reviewer;DecidedAtUtc=decidedAt.ToUniversalTime();}public OrganizationId OrganizationId{get;private set;}public PersonId StudentId{get;private set;}public TrainingPathId TrainingPathId{get;private set;}public PedagogicalReadinessDecisionStatus Decision{get;private set;}public string Rationale{get;private set;}=string.Empty;public string? Conditions{get;private set;}public UserId ReviewerId{get;private set;}public DateTimeOffset DecidedAtUtc{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public UserId? CreatedByUserId{get;private set;}public DateTimeOffset? LastModifiedAtUtc{get;private set;}public UserId? LastModifiedByUserId{get;private set;}public static Result<PedagogicalReadinessDecision> Record(PedagogicalReadinessDecisionId id,OrganizationId org,PersonId student,TrainingPathId path,PedagogicalReadinessDecisionStatus decision,string rationale,string? conditions,UserId reviewer,DateTimeOffset at){if(id.IsEmpty)return Result.Failure<PedagogicalReadinessDecision>(PedagogicalReadinessDecisionErrors.InvalidIdentifier);if(org.IsEmpty)return Result.Failure<PedagogicalReadinessDecision>(PedagogicalReadinessDecisionErrors.InvalidOrganization);if(student.IsEmpty)return Result.Failure<PedagogicalReadinessDecision>(PedagogicalReadinessDecisionErrors.InvalidStudent);if(path.IsEmpty)return Result.Failure<PedagogicalReadinessDecision>(PedagogicalReadinessDecisionErrors.InvalidTrainingPath);if(reviewer.IsEmpty)return Result.Failure<PedagogicalReadinessDecision>(PedagogicalReadinessDecisionErrors.InvalidReviewer);if(!Enum.IsDefined(decision)||string.IsNullOrWhiteSpace(rationale)||rationale.Trim().Length>4000)return Result.Failure<PedagogicalReadinessDecision>(PedagogicalReadinessDecisionErrors.InvalidRationale);if(decision==PedagogicalReadinessDecisionStatus.ReadyWithConditions&&string.IsNullOrWhiteSpace(conditions))return Result.Failure<PedagogicalReadinessDecision>(PedagogicalReadinessDecisionErrors.ConditionsRequired);var x=new PedagogicalReadinessDecision(id,org,student,path,decision,rationale.Trim(),string.IsNullOrWhiteSpace(conditions)?null:conditions.Trim(),reviewer,at);x.RaiseDomainEvent(new PedagogicalReadinessDecisionRecordedDomainEvent(x.Id,org,student,path,decision,reviewer));if(decision is PedagogicalReadinessDecisionStatus.Ready or PedagogicalReadinessDecisionStatus.ReadyWithConditions)x.RaiseDomainEvent(new StudentMarkedPedagogicallyReadyDomainEvent(x.Id,org,student,path,reviewer));return Result.Success(x);}public void SetCreatedAudit(DateTimeOffset at,UserId? by){if(CreatedAtUtc!=default)return;CreatedAtUtc=at.ToUniversalTime();CreatedByUserId=by;}public void SetModifiedAudit(DateTimeOffset at,UserId? by){LastModifiedAtUtc=at.ToUniversalTime();LastModifiedByUserId=by;}}
